//! Auto-match std imports (LINE-AUTOMATCH-IMPL; plan:
//! ~/workspace/sla-prelude/PLAN.md, user ruling 2026-11-18).
//!
//! Mechanism: when a name used by the program is not defined by
//! the program itself, by an explicit `@import`, or by a checker
//! builtin, the pipeline consults the std index
//! (`sla_std/automatch_index.tsv`, generated by
//! scripts/gen_automatch_index.py from the same std surface the
//! thin wrappers are generated from). A name with exactly ONE
//! providing std module gets that module imported through the
//! ordinary import machinery — the same road an explicit
//! `@import` takes (expansion, contract load, registration,
//! freshness closure). A name with two or more providers is a
//! loud error listing the candidates. Local definitions and
//! explicit imports always win: auto-match only ever fires for
//! names nothing else resolved.
//!
//! This module is the data + analysis half: index loading, the
//! known-name set, the syntactic candidate scan, and the
//! undefined-name extraction from checker diagnostics. The
//! pipeline owns the retry loop that acts on the plan.

use sla_ast::node::Node;
use sla_ast::{Program, Type};
use sla_checker::{Checker, Diagnostic, ErrorKind};
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::path::Path;

/// The index's import-style path; resolved through the same
/// sla_std resolution as any `sla_std/...` import, so the index
/// is found wherever the std it describes is found.
pub const INDEX_IMPORT_PATH: &str = "sla_std/automatch_index.tsv";

/// One std module's declaration of a name.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Provider {
    /// fn / type / macro / extern / const (generator vocabulary).
    pub kind: String,
    /// Import path as written in source, e.g.
    /// `sla_std/wrap/io.sla` or `sa_std/string.sa`.
    pub module: String,
}

/// The parsed index: name -> providers in file order.
#[derive(Debug, Default)]
pub struct AutomatchIndex {
    by_name: HashMap<String, Vec<Provider>>,
}

impl AutomatchIndex {
    pub fn parse(source: &str) -> AutomatchIndex {
        let mut by_name: HashMap<String, Vec<Provider>> = HashMap::new();
        for line in source.lines() {
            let line = line.trim_end();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let mut parts = line.split('\t');
            let (Some(name), Some(kind), Some(module)) =
                (parts.next(), parts.next(), parts.next())
            else {
                continue;
            };
            let provider = Provider {
                kind: kind.to_string(),
                module: module.to_string(),
            };
            let entry = by_name.entry(name.to_string()).or_default();
            if !entry.contains(&provider) {
                entry.push(provider);
            }
        }
        AutomatchIndex { by_name }
    }

    /// Load the index through the sla_std resolution machinery.
    /// Returns the index and the canonical on-disk path (the
    /// pipeline files the path into the freshness closure, so a
    /// std/index change invalidates cached artifacts). `None`
    /// when no index is resolvable: auto-match is then simply
    /// off and every name resolves exactly as before.
    pub fn load(base_dir: &Path) -> Option<(AutomatchIndex, String)> {
        let resolved =
            sla_parser::imports::resolve_import_file(base_dir, INDEX_IMPORT_PATH).ok()?;
        let index = AutomatchIndex::parse(&resolved.source);
        Some((index, resolved.path))
    }

    pub fn providers(&self, name: &str) -> &[Provider] {
        self.by_name.get(name).map(Vec::as_slice).unwrap_or(&[])
    }

    /// Distinct providing modules for `name`, in index order.
    pub fn modules_for(&self, name: &str) -> Vec<String> {
        let mut modules: Vec<String> = Vec::new();
        for provider in self.providers(name) {
            if !modules.contains(&provider.module) {
                modules.push(provider.module.clone());
            }
        }
        modules
    }
}

/// Names the checker resolves without any import (the
/// check_builtin.rs bare-name special block plus the
/// checker_util.rs panic pair). They are never auto-match
/// candidates: the builtin arm runs before any undefined
/// fallback, so importing a module for one of these names
/// would be pure noise.
const SPECIAL_NAMES: &[&str] = &[
    "vec",
    "len",
    "str_eq",
    "format",
    "hash",
    "debug",
    "println",
    "std__panic__catch_unwind",
    "panic",
    "panic_msg",
];

/// Every name already resolved before auto-match may fire:
/// the checker's registries (extern contracts, imported
/// macros, IMP-4 imported signatures, program decls the
/// checker pre-registered) plus the program's own top-level
/// declaration names plus the builtin specials. A candidate
/// outside this set is, by construction, a name the checker
/// would report undefined.
pub fn known_names(checker: &Checker, program: &Program) -> HashSet<String> {
    let mut known: HashSet<String> = HashSet::new();
    for key in checker.funcs.keys() {
        known.insert(key.clone());
    }
    for key in checker.func_overload_sets.keys() {
        known.insert(key.clone());
    }
    for key in checker.extern_funcs.keys() {
        known.insert(key.clone());
    }
    for key in checker.extern_overload_sets.keys() {
        known.insert(key.clone());
    }
    for key in checker.imported_funcs.keys() {
        known.insert(key.clone());
    }
    for key in checker.imported_overload_sets.keys() {
        known.insert(key.clone());
    }
    for key in checker.macros.keys() {
        known.insert(key.clone());
    }
    for key in checker.imported_macros.keys() {
        known.insert(key.clone());
    }
    for key in checker.structs.keys() {
        known.insert(key.clone());
    }
    for key in checker.enums.keys() {
        known.insert(key.clone());
    }
    for key in checker.aliases.keys() {
        known.insert(key.clone());
    }
    for key in checker.traits.keys() {
        known.insert(key.clone());
    }
    for decl in &program.decls {
        match decl {
            Node::FuncDecl(fd) => {
                known.insert(fd.name.clone());
            }
            Node::StructDecl(sd) => {
                known.insert(sd.name.clone());
            }
            Node::EnumDecl(ed) => {
                known.insert(ed.name.clone());
            }
            Node::TraitDecl(td) => {
                known.insert(td.name.clone());
            }
            Node::TypeAliasDecl(td) => {
                known.insert(td.name.clone());
            }
            Node::ConstStmt(cs) => {
                known.insert(cs.name.clone());
            }
            Node::MacroDecl(md) => {
                known.insert(md.name.clone());
            }
            Node::ImplDecl(impl_decl) => {
                for method in &impl_decl.methods {
                    if let Node::FuncDecl(fd) = method {
                        known.insert(fd.name.clone());
                    }
                }
            }
            Node::OverloadDecl(overload_decl) => {
                for method in &overload_decl.methods {
                    if let Node::FuncDecl(fd) = method {
                        known.insert(fd.name.clone());
                    }
                }
            }
            _ => {}
        }
    }
    for name in SPECIAL_NAMES {
        known.insert((*name).to_string());
    }
    known
}

/// Plan the auto-match for one scan round: names resolving to
/// exactly one not-yet-imported module become new imports;
/// names with two or more providers are recorded as ambiguous
/// (the pipeline reports them loudly if the checker then proves
/// the name really is unresolved). Names with no provider are
/// left alone — the checker's ordinary undefined diagnostic
/// stands for them.
pub fn plan_matches(
    index: &AutomatchIndex,
    candidates: &[String],
    already_imported: &HashSet<String>,
) -> (Vec<(String, String)>, BTreeMap<String, Vec<String>>) {
    let mut new_matches: Vec<(String, String)> = Vec::new();
    let mut ambiguous: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for name in candidates {
        let modules = index.modules_for(name);
        match modules.len() {
            0 => {}
            1 => {
                let module = modules.into_iter().next().unwrap();
                if !already_imported.contains(&module)
                    && !new_matches.iter().any(|(_, m)| *m == module)
                {
                    new_matches.push((name.clone(), module));
                }
            }
            _ => {
                ambiguous.insert(name.clone(), modules);
            }
        }
    }
    (new_matches, ambiguous)
}

/// The name a checker diagnostic proved unresolved, when the
/// diagnostic is one of the undefined shapes. Message shapes
/// (checker sites): `Undefined call: {name}` and
/// ``UndefinedVariable: `{name}` `` — both carry
/// ErrorKind::UndefinedVariable.
pub fn undefined_name(diag: &Diagnostic) -> Option<String> {
    if diag.kind != ErrorKind::UndefinedVariable {
        return None;
    }
    let message = diag.message.as_str();
    if let Some(rest) = message.strip_prefix("Undefined call: ") {
        let name = rest.trim().trim_matches('`');
        if !name.is_empty() {
            return Some(name.to_string());
        }
        return None;
    }
    if let Some(rest) = message.strip_prefix("UndefinedVariable: `") {
        if let Some(end) = rest.find('`') {
            if end > 0 {
                return Some(rest[..end].to_string());
            }
        }
    }
    None
}

// -- candidate scan ---------------------------------------------------
//
// A syntactic walk over the (expanded) program collecting the
// global names it references: free calls, function references,
// identifiers, associated-call targets, and user-defined type
// names. Over-collection is safe by design: a collected name
// that is actually a local binding simply misses the index (or
// hits a module whose import cannot shadow the local — checker
// scopes resolve first), and a name that hits nothing changes
// nothing. Under-collection only narrows the feature: the
// checker's diagnostic path in the pipeline covers shapes this
// walk does not reach.

fn record_type(found: &mut BTreeSet<String>, ty: &Type) {
    crate::test_reach::record_referenced_type(found, ty);
}

fn walk_expr(expr: &Node, found: &mut BTreeSet<String>) {
    match expr {
        Node::Identifier(name) => {
            found.insert(name.clone());
        }
        Node::GenericFuncRef(gref) => {
            found.insert(gref.func_name.clone());
            for ty in &gref.generics {
                record_type(found, ty);
            }
        }
        Node::CallExpr(call) => {
            if let Some(callee) = &call.callee {
                walk_expr(callee, found);
            }
            if let Some(target) = &call.associated_target {
                found.insert(target.clone());
            } else {
                found.insert(call.func_name.clone());
            }
            for ty in &call.generics {
                record_type(found, ty);
            }
            for arg in &call.args {
                walk_expr(arg, found);
            }
        }
        Node::IfExpr(ife) => {
            walk_expr(&ife.cond, found);
            if let Some(chain) = &ife.let_chain {
                for cond in chain {
                    walk_expr(&cond.value, found);
                }
            }
            walk_block(&ife.then_block, found);
            if let Some(else_block) = &ife.else_block {
                walk_block(else_block, found);
            }
        }
        Node::SwitchExpr(swe) => {
            walk_expr(&swe.val, found);
            for case in &swe.cases {
                walk_expr(&case.pattern, found);
                walk_block(&case.body, found);
            }
        }
        Node::MatchExpr(mat) => {
            walk_expr(&mat.val, found);
            for case in &mat.cases {
                if let Some(guard) = &case.guard {
                    walk_expr(guard, found);
                }
                walk_block(&case.body, found);
            }
        }
        Node::UnsafeExpr(unsafe_expr) => walk_block(&unsafe_expr.body, found),
        Node::AwaitExpr(await_expr) => walk_expr(&await_expr.expr, found),
        Node::TryExpr(try_expr) => walk_expr(&try_expr.expr, found),
        Node::GoStmt(go_stmt) => walk_expr(&go_stmt.call, found),
        Node::DeferStmt(defer_stmt) => walk_expr(&defer_stmt.call, found),
        Node::SelectStmt(select) => {
            for arm in &select.arms {
                if let Some(recv) = &arm.recv {
                    walk_expr(recv, found);
                }
                walk_block(&arm.body, found);
            }
            if let Some(timeout) = &select.timeout {
                walk_expr(&timeout.expr, found);
                walk_block(&timeout.body, found);
            }
        }
        Node::BinaryExpr(bin) => {
            walk_expr(&bin.left, found);
            walk_expr(&bin.right, found);
        }
        Node::ClosureLiteral(closure) => walk_expr(&closure.body, found),
        Node::BorrowExpr(borrow) => walk_expr(&borrow.expr, found),
        Node::MoveExpr(mv) => walk_expr(&mv.expr, found),
        Node::DerefExpr(deref) => walk_expr(&deref.expr, found),
        Node::CastExpr(cast) => {
            record_type(found, &cast.ty);
            walk_expr(&cast.expr, found);
        }
        Node::FieldExpr(field) => walk_expr(&field.expr, found),
        Node::StructLiteral(lit) => {
            record_type(found, &lit.ty);
            for field in &lit.fields {
                walk_expr(&field.value, found);
            }
            if let Some(update) = &lit.update_expr {
                walk_expr(update, found);
            }
        }
        Node::EnumLiteral(lit) => {
            found.insert(lit.enum_name.clone());
            for field in &lit.fields {
                walk_expr(&field.value, found);
            }
        }
        Node::TupleLiteral(lit) => {
            for elem in &lit.elements {
                walk_expr(elem, found);
            }
        }
        Node::ArrayLiteral(lit) => {
            for elem in &lit.elements {
                walk_expr(elem, found);
            }
        }
        Node::RepeatArrayLiteral(lit) => walk_expr(&lit.value, found),
        Node::IndexExpr(idx) => {
            walk_expr(&idx.target, found);
            walk_expr(&idx.index, found);
        }
        Node::SliceExpr(slice) => {
            walk_expr(&slice.target, found);
            walk_expr(&slice.start, found);
            walk_expr(&slice.end, found);
        }
        _ => {}
    }
}

fn walk_block(block: &[Node], found: &mut BTreeSet<String>) {
    for stmt in block {
        match stmt {
            Node::LetStmt(let_stmt) => {
                if let Some(ty) = &let_stmt.ty {
                    record_type(found, ty);
                }
                walk_expr(&let_stmt.value, found);
            }
            Node::VarStmt(var_stmt) => record_type(found, &var_stmt.ty),
            Node::LetElseStmt(let_else) => {
                walk_expr(&let_else.value, found);
                walk_block(&let_else.else_block, found);
            }
            Node::LetDestructureStmt(let_dest) => walk_expr(&let_dest.value, found),
            Node::ConstStmt(const_stmt) => {
                if let Some(ty) = &const_stmt.ty {
                    record_type(found, ty);
                }
                walk_expr(&const_stmt.value, found);
            }
            Node::AssignStmt(assign) => {
                walk_expr(&assign.target, found);
                walk_expr(&assign.value, found);
            }
            Node::BlockStmt(block_stmt) => walk_block(&block_stmt.body, found),
            Node::ArenaStmt(block_stmt) => walk_block(&block_stmt.body, found),
            Node::ExprStmt(expr) => walk_expr(expr, found),
            Node::ReturnStmt(ret) => {
                if let Some(value) = &ret.value {
                    walk_expr(value, found);
                }
            }
            Node::ForStmt(for_stmt) => {
                walk_expr(&for_stmt.start, found);
                if let Some(end) = &for_stmt.end {
                    walk_expr(end, found);
                }
                walk_block(&for_stmt.body, found);
            }
            Node::WhileStmt(while_stmt) => {
                walk_expr(&while_stmt.cond, found);
                walk_block(&while_stmt.body, found);
            }
            _ => walk_expr(stmt, found),
        }
    }
}

fn walk_decl(decl: &Node, found: &mut BTreeSet<String>) {
    match decl {
        Node::FuncDecl(fd) => {
            for param in &fd.params {
                record_type(found, &param.ty);
            }
            record_type(found, &fd.ret_ty);
            walk_block(&fd.body, found);
        }
        Node::TestDecl(test_decl) => walk_block(&test_decl.body, found),
        Node::ConstStmt(const_stmt) => {
            if let Some(ty) = &const_stmt.ty {
                record_type(found, ty);
            }
            walk_expr(&const_stmt.value, found);
        }
        Node::MacroDecl(macro_decl) => walk_block(&macro_decl.body, found),
        Node::ImplDecl(impl_decl) => {
            record_type(found, &impl_decl.target_ty);
            for method in &impl_decl.methods {
                walk_decl(method, found);
            }
        }
        Node::OverloadDecl(overload_decl) => {
            record_type(found, &overload_decl.target_ty);
            for method in &overload_decl.methods {
                walk_decl(method, found);
            }
        }
        Node::StructDecl(struct_decl) => {
            for field in &struct_decl.fields {
                record_type(found, &field.ty);
            }
        }
        Node::EnumDecl(enum_decl) => {
            for variant in &enum_decl.variants {
                for field in &variant.fields {
                    record_type(found, &field.ty);
                }
            }
        }
        Node::TraitDecl(trait_decl) => {
            for method in &trait_decl.methods {
                for param in &method.params {
                    record_type(found, &param.ty);
                }
                record_type(found, &method.ret_ty);
            }
        }
        _ => {}
    }
}

/// All referenced global names in `program` that are not in
/// `known`, sorted (deterministic match order).
pub fn collect_candidates(program: &Program, known: &HashSet<String>) -> Vec<String> {
    let mut found: BTreeSet<String> = BTreeSet::new();
    for decl in &program.decls {
        walk_decl(decl, &mut found);
    }
    found.retain(|name| !known.contains(name));
    found.into_iter().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn index_parse_skips_comments_and_dedups() {
        let index = AutomatchIndex::parse(
            "# header\n\
             sla_fmt_u64\tfn\tsla_std/wrap/fmt.sla\n\
             sla_fmt_u64\tfn\tsla_std/wrap/fmt.sla\n\
             dup\tfn\tsla_std/wrap/a.sla\n\
             dup\tfn\tsla_std/wrap/b.sla\n\
             broken line without tabs\n",
        );
        assert_eq!(index.modules_for("sla_fmt_u64"), vec!["sla_std/wrap/fmt.sla"]);
        assert_eq!(
            index.modules_for("dup"),
            vec!["sla_std/wrap/a.sla", "sla_std/wrap/b.sla"]
        );
        assert!(index.modules_for("missing").is_empty());
    }

    #[test]
    fn plan_matches_splits_unique_and_ambiguous() {
        let index = AutomatchIndex::parse(
            "one\tfn\tm/one.sla\ntwo\tfn\tm/a.sla\ntwo\tfn\tm/b.sla\n",
        );
        let candidates = vec!["one".to_string(), "two".to_string(), "none".to_string()];
        let (new_matches, ambiguous) =
            plan_matches(&index, &candidates, &HashSet::new());
        assert_eq!(
            new_matches,
            vec![("one".to_string(), "m/one.sla".to_string())]
        );
        assert_eq!(
            ambiguous.get("two").map(Vec::as_slice),
            Some(["m/a.sla".to_string(), "m/b.sla".to_string()].as_slice())
        );
        // An already-imported module is not re-matched.
        let mut imported = HashSet::new();
        imported.insert("m/one.sla".to_string());
        let (new_matches, _) = plan_matches(&index, &candidates, &imported);
        assert!(new_matches.is_empty());
    }

    #[test]
    fn undefined_name_extraction_shapes() {
        let call = Diagnostic::new(ErrorKind::UndefinedVariable, "Undefined call: foo_bar");
        assert_eq!(undefined_name(&call).as_deref(), Some("foo_bar"));
        let var = Diagnostic::new(
            ErrorKind::UndefinedVariable,
            "UndefinedVariable: `some_name`",
        );
        assert_eq!(undefined_name(&var).as_deref(), Some("some_name"));
        let other = Diagnostic::new(ErrorKind::TypeMismatch, "Undefined call: foo_bar");
        assert_eq!(undefined_name(&other), None);
        let mismatch = Diagnostic::new(ErrorKind::TypeMismatch, "TypeMismatch: x");
        assert_eq!(undefined_name(&mismatch), None);
    }

    #[test]
    fn candidates_exclude_known_and_builtins() {
        let source = "fn helper() -> i32 { return 1; }\n\
                      fn main() -> i32 {\n\
                          println(\"x\");\n\
                          return helper() + (sla_fmt_u64(3, 10) as i32);\n\
                      }\n";
        let mut parser = sla_parser::Parser::new(source);
        let root = parser.parse_program().unwrap();
        let Node::Program(program) = root else {
            panic!("expected a program");
        };
        let checker = Checker::new();
        let known = known_names(&checker, &program);
        let candidates = collect_candidates(&program, &known);
        assert_eq!(candidates, vec!["sla_fmt_u64".to_string()]);
    }
}
